/**
 * PyPath trail map: scroll progress draws each segment's line, lights its stops
 * and labels the active one.
 *
 * The markup is generated by scripts/build-trail.mjs: one <svg class="path-map"
 * data-segment> per course, stacked in one sticky viewport. Stops arrive already
 * placed (the generator lays them out on a serpentine and routes the line
 * through them), each with data-at, the fraction of the path where it sits.
 * Overall progress through the track is divided between segments and the seams
 * between them by their scroll budgets (data-span, data-seam):
 *
 *   [ segment 1 ][ seam ][ segment 2 ]
 *
 * Inside a segment, scroll moves stop to stop at an even pace, with a short
 * dwell on the first and last stop. The line is drawn to exactly the point the
 * traveller has reached, so a stop lights when the line arrives at it. Across a
 * seam the maps cross-fade (--seam 0..1), the section's data-scene switches at
 * the midpoint, and the head is hidden until the next map is fully in.
 *
 * Labels: the map shows numbers only. The active stop gets one label in a pill
 * with a leader line; a stop under the pointer gets a second. Label positions
 * are chosen by measurement, never by index: each label is measured with
 * getBBox(), tried on both sides of the path's normal and above and below its
 * dot, and the candidate that stays inside the map and clear of other stops and
 * of the line wins. That runs once on load and again on resize, and the results
 * are cached, so the scroll handler only reads numbers.
 */
(function () {
  const section = document.querySelector("[data-path-journey]");
  if (!section) return;

  const track = section.querySelector(".path-journey__track");
  const reduced =
    document.documentElement.classList.contains("reduced-motion") ||
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const cards = Array.from(section.querySelectorAll("[data-stop-card]"));
  const countEl = section.querySelector("[data-trail-count]");
  const jumps = Array.from(section.querySelectorAll("[data-trail-jump]"));

  // Scroll dwell on each segment's first and last stop, as fractions of the
  // segment's own scroll budget.
  const DWELL_START = 0.03;
  const DWELL_END = 0.06;
  const ACTIVE_SCALE = 1.4;
  const DOT_R = 13;
  const LABEL_GAP = 12; // viewBox units between a dot's edge and its label
  const LEADER_MIN = 12; // a hovered label further than this gets a leader

  const clamp01 = (x) => Math.min(1, Math.max(0, x));
  const smooth = (a, b, x) => {
    const t = clamp01((x - a) / (b - a));
    return t * t * (3 - 2 * t);
  };

  let offset = 0;
  const segments = Array.from(section.querySelectorAll(".path-map[data-segment]")).map((svg) => {
    const stops = Array.from(svg.querySelectorAll("[data-stop]")).map((el, i) => {
      const m = /translate\(\s*([-\d.]+)[ ,]+([-\d.]+)\s*\)/.exec(el.getAttribute("transform") || "");
      return {
        el,
        local: i,
        index: Number(el.getAttribute("data-stop-index")),
        at: Number(el.getAttribute("data-at")),
        label: el.getAttribute("data-label") || "",
        x: m ? Number(m[1]) : 0,
        y: m ? Number(m[2]) : 0,
        reach: el.classList.contains("trail-stop--start") ? 22 : DOT_R,
        // The finish flag stands up and to the right of its dot; labels keep
        // clear of it as they do of other stops.
        flag: el.classList.contains("trail-stop--end") ? { x: 8, y: -38, w: 23, h: 30 } : null,
      };
    });
    const seg = {
      svg,
      scene: svg.getAttribute("data-segment"),
      span: Math.max(0, Number(svg.getAttribute("data-span")) || 1),
      seam: Math.max(0, Number(svg.getAttribute("data-seam")) || 0),
      drawPath: svg.querySelector(".path-map__draw"),
      head: svg.querySelector(".path-head"),
      callout: svg.querySelector(".trail-callout:not(.trail-callout--peek)"),
      peek: svg.querySelector(".trail-callout--peek"),
      stops,
      offset,
      start: 0,
      end: 0,
      len: 0,
      box: { w: 560, h: 400 },
      samples: [],
      labels: [],
      state: { active: -2, lit: -2, peek: -1 },
    };
    offset += stops.length;
    return seg;
  });
  if (!segments.length) return;
  const totalStops = offset;

  /* Divide overall progress 0..1 between segments and seams by their budgets. */
  function layout() {
    const total =
      segments.reduce((sum, seg, i) => sum + seg.span + (i < segments.length - 1 ? seg.seam : 0), 0) || 1;
    let at = 0;
    segments.forEach((seg, i) => {
      seg.start = at / total;
      at += seg.span;
      seg.end = at / total;
      if (i < segments.length - 1) at += seg.seam;
    });
  }

  /* Where overall progress p lands: the scene on show, and how far through a
     seam's cross-fade we are. */
  function locate(p) {
    let sceneIndex = 0;
    let seamT = 0;
    let seamIndex = -1;
    for (let i = 0; i < segments.length; i++) {
      const seg = segments[i];
      if (p >= seg.start) sceneIndex = i;
      const next = segments[i + 1];
      if (next && p > seg.end && p < next.start) {
        seamIndex = i;
        seamT = clamp01((p - seg.end) / (next.start - seg.end));
        sceneIndex = seamT < 0.5 ? i : i + 1;
      }
    }
    return { sceneIndex, seamIndex, seamT };
  }

  /* Stop-space position (0..n-1) for a segment-local scroll fraction u. */
  function stopPosition(seg, u) {
    const n = seg.stops.length;
    if (n < 2) return 0;
    return clamp01((u - DWELL_START) / (1 - DWELL_START - DWELL_END)) * (n - 1);
  }

  /* Fraction along the path for a stop-space position. */
  function pathFraction(seg, k) {
    const n = seg.stops.length;
    if (!n) return 0;
    const i = Math.min(n - 1, Math.floor(k));
    const j = Math.min(n - 1, i + 1);
    const t = k - i;
    return seg.stops[i].at + (seg.stops[j].at - seg.stops[i].at) * t;
  }

  /* ── Label measurement (load and resize only) ─────────────────────────── */

  function rectHitsCircle(r, cx, cy, rad) {
    const nx = Math.max(r.x, Math.min(cx, r.x + r.w));
    const ny = Math.max(r.y, Math.min(cy, r.y + r.h));
    return (nx - cx) * (nx - cx) + (ny - cy) * (ny - cy) < rad * rad;
  }

  function distanceToRect(x, y, r) {
    const dx = Math.max(r.x - x, 0, x - (r.x + r.w));
    const dy = Math.max(r.y - y, 0, y - (r.y + r.h));
    return Math.hypot(dx, dy);
  }

  function rectsHit(a, b, pad = 0) {
    return a.x < b.x + b.w + pad && b.x < a.x + a.w + pad && a.y < b.y + b.h + pad && b.y < a.y + a.h + pad;
  }

  function markScale(seg) {
    const v = parseFloat(getComputedStyle(seg.svg).getPropertyValue("--mark-scale"));
    return Number.isFinite(v) && v > 0 ? v : 1;
  }

  function measureSegment(seg) {
    const vb = seg.svg.viewBox && seg.svg.viewBox.baseVal;
    if (vb && vb.width) seg.box = { w: vb.width, h: vb.height };
    const path = seg.drawPath;
    if (!path || typeof path.getTotalLength !== "function") return;
    try {
      seg.len = path.getTotalLength();
    } catch (_) {
      return;
    }
    if (!seg.len) return;

    seg.samples = [];
    for (let i = 0; i <= 240; i++) {
      const pt = path.getPointAtLength((i / 240) * seg.len);
      seg.samples.push({ x: pt.x, y: pt.y });
    }

    const scale = markScale(seg);
    const text = seg.callout && seg.callout.querySelector(".trail-callout__text");
    if (!text) return;
    const fontSize = parseFloat(getComputedStyle(text).fontSize) || 14;
    const original = text.textContent;
    const { w: W, h: H } = seg.box;
    const margin = 4;

    seg.labels = seg.stops.map((stop) => {
      text.textContent = stop.label;
      let bb;
      try {
        bb = text.getBBox();
      } catch (_) {
        bb = { width: 0, height: 0 };
      }
      if (!bb.width) bb = { width: stop.label.length * fontSize * 0.55, height: fontSize };
      const w = bb.width + fontSize * 1.8;
      const h = Math.max(bb.height, fontSize) + fontSize * 0.9;
      const reach = stop.reach * scale * ACTIVE_SCALE;

      // Tangent at the stop, from the path itself.
      const l = stop.at * seg.len;
      const a = path.getPointAtLength(Math.max(0, l - 3));
      const b = path.getPointAtLength(Math.min(seg.len, l + 3));
      let tx = b.x - a.x;
      let ty = b.y - a.y;
      const tl = Math.hypot(tx, ty) || 1;
      tx /= tl;
      ty /= tl;
      // Both sides of the normal first, then the compass points and diagonals.
      const D = Math.SQRT1_2;
      const dirs = [
        { x: -ty, y: tx },
        { x: ty, y: -tx },
        { x: 0, y: -1 },
        { x: 0, y: 1 },
        { x: -1, y: 0 },
        { x: 1, y: 0 },
        { x: -D, y: -D },
        { x: D, y: -D },
        { x: -D, y: D },
        { x: D, y: D },
      ];

      const cands = [];
      dirs.forEach((dir, di) => {
        const extent = Math.abs(dir.x) * (w / 2) + Math.abs(dir.y) * (h / 2);
        const dist = reach + LABEL_GAP + extent;
        let cx = stop.x + dir.x * dist;
        let cy = stop.y + dir.y * dist;
        // Keep inside the map; sliding along an edge is allowed.
        cx = Math.min(W - margin - w / 2, Math.max(margin + w / 2, cx));
        cy = Math.min(H - margin - h / 2, Math.max(margin + h / 2, cy));
        const rect = { x: cx - w / 2, y: cy - h / 2, w, h };
        let penalty = di < 2 ? 0 : 1 + di * 0.2; // prefer the normal when everything else is equal
        if (rectHitsCircle(rect, stop.x, stop.y, reach + 2)) penalty += 1000;
        if (stop.flag) {
          const k = 1;
          const f = { x: stop.x + stop.flag.x * k - 4, y: stop.y + stop.flag.y * k - 4, w: stop.flag.w * k + 8, h: stop.flag.h * k + 8 };
          if (rectsHit(rect, f)) penalty += 800;
        }
        const own = distanceToRect(stop.x, stop.y, rect);
        seg.stops.forEach((other) => {
          if (other === stop) return;
          if (rectHitsCircle(rect, other.x, other.y, other.reach * scale * ACTIVE_SCALE + 8)) penalty += 400;
          // A label must read as belonging to its own dot: no other dot nearer.
          if (distanceToRect(other.x, other.y, rect) <= own + 6) penalty += 600;
        });
        seg.samples.forEach((s) => {
          if (s.x > rect.x - 3 && s.x < rect.x + rect.w + 3 && s.y > rect.y - 3 && s.y < rect.y + rect.h + 3) penalty += 3;
        });
        // More free space on this side of the map scores better.
        const free = Math.min(rect.x, W - rect.x - rect.w, rect.y, H - rect.y - rect.h);
        penalty -= Math.min(free, 60) * 0.05;
        cands.push({ penalty, rect, dir });
      });
      cands.sort((x, y) => x.penalty - y.penalty);
      return { rect: cands[0].rect, dir: cands[0].dir, reach, cands };
    });
    text.textContent = original;
  }

  function measure() {
    segments.forEach(measureSegment);
  }

  /* ── Drawing labels (numbers only, from the cache) ────────────────────── */

  function leaderFor(stop, rect, reach) {
    const nx = Math.max(rect.x, Math.min(stop.x, rect.x + rect.w));
    const ny = Math.max(rect.y, Math.min(stop.y, rect.y + rect.h));
    const dx = nx - stop.x;
    const dy = ny - stop.y;
    const d = Math.hypot(dx, dy) || 1;
    return { x1: stop.x + (dx / d) * (reach + 2), y1: stop.y + (dy / d) * (reach + 2), x2: nx, y2: ny, length: d - reach };
  }

  function drawLabel(group, stop, rect, reach, alwaysLeader) {
    if (!group) return;
    const pill = group.querySelector(".trail-callout__pill");
    const text = group.querySelector(".trail-callout__text");
    const leader = group.querySelector(".trail-callout__leader");
    group.setAttribute("transform", "translate(0 0)");
    group.setAttribute("data-for", String(stop.index));
    text.textContent = stop.label;
    text.setAttribute("x", String(rect.x + rect.w / 2));
    text.setAttribute("y", String(rect.y + rect.h / 2));
    pill.setAttribute("x", String(rect.x));
    pill.setAttribute("y", String(rect.y));
    pill.setAttribute("width", String(rect.w));
    pill.setAttribute("height", String(rect.h));
    pill.setAttribute("rx", String(rect.h / 2));
    const l = leaderFor(stop, rect, reach);
    const show = alwaysLeader || l.length > LEADER_MIN;
    leader.setAttribute("x1", String(l.x1));
    leader.setAttribute("y1", String(l.y1));
    leader.setAttribute("x2", String(l.x2));
    leader.setAttribute("y2", String(l.y2));
    leader.style.display = show ? "" : "none";
    group.classList.add("is-shown");
  }

  function hideLabel(group) {
    if (!group) return;
    group.classList.remove("is-shown");
    group.removeAttribute("data-for");
  }

  function renderLabels(seg) {
    const active = seg.state.active;
    const cache = seg.labels;
    if (!cache.length || active < 0) {
      hideLabel(seg.callout);
      hideLabel(seg.peek);
      return;
    }
    const a = cache[active];
    drawLabel(seg.callout, seg.stops[active], a.rect, a.reach, true);

    const pi = seg.state.peek;
    if (pi < 0 || pi === active || !cache[pi]) {
      hideLabel(seg.peek);
      return;
    }
    // The hovered stop's label takes its best measured position that stays
    // clear of the active label and still reads as its own dot's; failing
    // that, it is pushed apart along its side, and if nothing works it waits.
    const p = cache[pi];
    const { w: W, h: H } = seg.box;
    const peekStop = seg.stops[pi];
    const ownsIt = (r) => {
      const own = distanceToRect(peekStop.x, peekStop.y, r);
      return seg.stops.every((o) => o === peekStop || distanceToRect(o.x, o.y, r) > own + 2);
    };
    let rect = null;
    for (const c of p.cands) {
      if (c.penalty < 400 && !rectsHit(c.rect, a.rect, 4) && ownsIt(c.rect)) {
        rect = c.rect;
        break;
      }
    }
    for (let ci = 0; !rect && ci < p.cands.length; ci++) {
      const c = p.cands[ci];
      const r = { ...c.rect };
      for (let pass = 0; pass < 10 && rectsHit(r, a.rect, 4); pass++) {
        r.x = Math.min(W - 4 - r.w, Math.max(4, r.x + c.dir.x * 8));
        r.y = Math.min(H - 4 - r.h, Math.max(4, r.y + c.dir.y * 8));
      }
      if (!rectsHit(r, a.rect, 4) && ownsIt(r)) rect = r;
    }
    if (!rect) {
      hideLabel(seg.peek);
      return;
    }
    drawLabel(seg.peek, peekStop, rect, p.reach, false);
  }

  /* ── Progress ─────────────────────────────────────────────────────────── */

  let lastProgress = 0;

  function setProgress(p, { stepped = reduced } = {}) {
    const progress = clamp01(p);
    lastProgress = progress;
    section.style.setProperty("--path-progress", String(progress));

    const where = locate(progress);
    const scene = segments[where.sceneIndex];
    const fading = where.seamIndex !== -1 && !stepped;
    section.setAttribute("data-scene", scene.scene);
    section.style.setProperty("--seam", String(fading ? where.seamT : where.sceneIndex > 0 ? 1 : 0));
    // The title card covers the map from 35% to 65% of the seam.
    const curtain = where.seamIndex === -1 ? 0 : stepped ? 1 : smooth(0, 0.35, where.seamT) * (1 - smooth(0.65, 1, where.seamT));
    section.style.setProperty("--seam-curtain", String(curtain));
    section.classList.toggle("is-seaming", where.seamIndex !== -1);

    let activeCard = 0;
    segments.forEach((seg, si) => {
      const isScene = si === where.sceneIndex;
      const width = seg.end - seg.start;
      const u = width > 0 ? clamp01((progress - seg.start) / width) : progress >= seg.start ? 1 : 0;
      // A course starts when its scroll does, or when its scene takes over at
      // the middle of the seam: its first stop, the gateway, lights on arrival.
      const started = si === 0 || progress >= seg.start || isScene;
      const k = started ? stopPosition(seg, u) : 0;
      const reachedIndex = started ? Math.floor(k + 1e-6) : -1;
      const frac = started ? pathFraction(seg, k) : 0;

      seg.svg.style.setProperty("--path-progress", String(frac));
      seg.svg.classList.toggle("is-scene", isScene);
      seg.svg.classList.toggle("is-receded", !isScene);

      // The outgoing map is gone by 60% of the seam and the incoming one starts
      // at 40%, so the two routes overlap only briefly.
      let opacity = isScene ? 1 : 0;
      if (fading && (si === where.seamIndex || si === where.seamIndex + 1)) {
        opacity = si === where.seamIndex ? 1 - smooth(0, 0.6, where.seamT) : smooth(0.4, 1, where.seamT);
      }
      seg.svg.style.setProperty("--segment-opacity", String(opacity));

      if (reachedIndex !== seg.state.lit) {
        seg.stops.forEach((stop, i) => stop.el.classList.toggle("is-lit", i <= reachedIndex));
        seg.state.lit = reachedIndex;
      }

      // Only the scene's segment has an active stop, so nothing hidden is ever
      // reported as the stop you are on.
      const active = isScene ? Math.max(0, reachedIndex) : -1;
      if (active !== seg.state.active) {
        seg.stops.forEach((stop, i) => stop.el.classList.toggle("is-active", i === active));
        const grew = active > seg.state.active;
        seg.state.active = active;
        renderLabels(seg);
        if (active >= 0 && grew && !reduced && seg.callout && seg.callout.animate) {
          const body = seg.callout.querySelector(".trail-callout__body");
          if (body) {
            body.animate([{ opacity: 0, transform: "scale(0.9)" }, { opacity: 1, transform: "scale(1)" }], {
              duration: 220,
              easing: "cubic-bezier(0.16, 1, 0.3, 1)",
            });
          }
        }
      }
      if (isScene) activeCard = seg.offset + active;

      if (seg.head) {
        const onShow = isScene && where.seamIndex === -1 && seg.len > 0;
        seg.head.classList.toggle("is-hidden", !onShow);
        if (onShow) {
          const pt = seg.drawPath.getPointAtLength(frac * seg.len);
          seg.head.setAttribute("transform", `translate(${pt.x} ${pt.y})`);
        }
      }
    });

    cards.forEach((card, i) => card.classList.toggle("is-active", i === activeCard));
    if (countEl) countEl.textContent = String(activeCard + 1);
    jumps.forEach((link) => {
      if (link.getAttribute("data-trail-jump") === scene.scene) link.setAttribute("aria-current", "true");
      else link.removeAttribute("aria-current");
    });
  }

  function measureScroll() {
    if (!track) return 0;
    const rect = track.getBoundingClientRect();
    const total = track.offsetHeight - window.innerHeight;
    if (total <= 0) return 0;
    return Math.min(Math.max(-rect.top, 0), total) / total;
  }

  /* Overall progress at which stop `index` (counted across segments) is reached. */
  function progressForStop(index) {
    for (const seg of segments) {
      const n = seg.stops.length;
      if (index < seg.offset + n) {
        const i = index - seg.offset;
        const u = n < 2 ? 0 : DWELL_START + (i / (n - 1)) * (1 - DWELL_START - DWELL_END);
        return Math.min(seg.end, seg.start + u * (seg.end - seg.start) + 0.0005);
      }
    }
    return 1;
  }

  function scrollToProgress(p) {
    if (!track) return;
    const total = track.offsetHeight - window.innerHeight;
    const top = track.getBoundingClientRect().top + window.scrollY;
    window.scrollTo({ top: Math.round(top + clamp01(p) * Math.max(0, total)), behavior: "instant" });
    render();
  }

  function render() {
    const p = measureScroll();
    setProgress(p);
    section.classList.toggle("is-active", reduced || (p > 0.002 && p < 0.998));
  }

  let ticking = false;
  function onScroll() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(() => {
      ticking = false;
      render();
    });
  }

  let resizeQueued = false;
  function onResize() {
    if (resizeQueued) return;
    resizeQueued = true;
    requestAnimationFrame(() => {
      resizeQueued = false;
      measure();
      segments.forEach((seg) => renderLabels(seg));
      render();
    });
  }

  layout();
  measure();
  if (reduced) section.classList.add("is-active");
  setProgress(measureScroll());

  /* Pointer: hovering a stop reveals its label; clicking it scrolls there. */
  segments.forEach((seg) => {
    seg.stops.forEach((stop) => {
      stop.el.addEventListener("pointerenter", () => {
        seg.state.peek = stop.local;
        renderLabels(seg);
      });
      stop.el.addEventListener("pointerleave", () => {
        if (seg.state.peek === stop.local) seg.state.peek = -1;
        renderLabels(seg);
      });
      stop.el.addEventListener("click", () => scrollToProgress(progressForStop(stop.index)));
    });
  });

  /* Keyboard: a card that takes focus scrolls the trail to its stop. The course
     switcher lands on a course's first stop and focuses its card. */
  const stage = section.querySelector(".path-panel__stage");
  if (stage && segments.length > 1) {
    stage.addEventListener("focusin", (e) => {
      const card = e.target.closest("[data-stop-card]");
      if (!card || card.classList.contains("is-active")) return;
      scrollToProgress(progressForStop(Number(card.getAttribute("data-stop-index"))));
    });
  }
  jumps.forEach((link) => {
    link.addEventListener("click", (e) => {
      const index = Number(link.getAttribute("data-stop-index"));
      const card = cards[index];
      if (!card) return;
      e.preventDefault();
      scrollToProgress(progressForStop(index));
      const target = card.querySelector("a");
      if (target) target.focus({ preventScroll: true });
    });
  });

  // Listen on window + body: legacy site CSS sometimes makes body the scrollport
  window.addEventListener("scroll", onScroll, { passive: true });
  document.body.addEventListener("scroll", onScroll, { passive: true });
  document.documentElement.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", onResize, { passive: true });
  // Web fonts change label widths; measure again once they are in.
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(onResize);
  onScroll();

  window.PyPathTrail = {
    locate,
    segments,
    setProgress,
    measure,
    progressForStop,
    scrollToProgress,
    get progress() {
      return lastProgress;
    },
    totalStops,
  };
})();
